V20 = *F6 + E20;
F2 = *F1+*F5+*F6+D2;
F3 = *F1+*F5+*F6+D3;
F4 = *F1+*F5+*F6+D4;
F5 = *F1+D5;
/VARIANCES
F1=1;
F6=1;
E1=*;
